CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;
CREATE TABLE assets (
    "Id" uuid NOT NULL,
    "CatalogId" uuid NOT NULL,
    "State" text NOT NULL,
    "Sha256" text NOT NULL,
    "Metadata" jsonb NOT NULL,
    "Revision" integer NOT NULL,
    CONSTRAINT "PK_assets" PRIMARY KEY ("Id")
);

CREATE TABLE job_attempts (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "JobKey" text NOT NULL,
    "Worker" text NOT NULL,
    "StartedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_job_attempts" PRIMARY KEY ("Id")
);

CREATE TABLE job_effects (
    "JobKey" text NOT NULL,
    "ProducedBy" text NOT NULL,
    "ProducedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_job_effects" PRIMARY KEY ("JobKey")
);

CREATE TABLE jobs (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "JobKey" text NOT NULL,
    "Payload" jsonb NOT NULL,
    "State" text NOT NULL,
    "Attempts" integer NOT NULL,
    "MaxAttempts" integer NOT NULL,
    "RunAfter" timestamp with time zone NOT NULL,
    "LeaseUntil" timestamp with time zone,
    "LeaseToken" uuid,
    "LockedBy" text,
    "LastError" text,
    "CompletedAt" timestamp with time zone,
    CONSTRAINT "PK_jobs" PRIMARY KEY ("Id")
);

CREATE INDEX "IX_assets_CatalogId_State" ON assets ("CatalogId", "State");

CREATE INDEX "IX_assets_Metadata" ON assets USING gin ("Metadata" jsonb_path_ops);

CREATE UNIQUE INDEX "IX_jobs_JobKey" ON jobs ("JobKey");

CREATE INDEX "IX_jobs_State_RunAfter" ON jobs ("State", "RunAfter") WHERE "State" in ('ready', 'running');

INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
VALUES ('20261126131724_Initial', '10.0.15');

COMMIT;

